def tokens_esperados(alfa, gama):
    return (1 - alfa ** (gama + 1)) / (1 - alfa)
def monte_carlo(alfa, gama, n=200_000, seed=0):
    aceitos = np.random.default_rng(seed).random((n, gama)) < alfa
    k = np.where(aceitos.all(1), gama, np.argmin(aceitos, 1))
    return (k + 1).mean()      # + 1 token do modelo grande
# experimento: alvo = trigramas, rascunhador = bigramas (corpus sintético)
